/* ==========================================================================
       01. EXACT COLOR TOKENS & SERIF-ONLY TYPOGRAPHY SYSTEM
       ========================================================================== */
    :root {
      --paper: #F5F1E8;          /* main page background; dominant */
      --paper-light: #FAF8F2;    /* card or inset surfaces */
      --ink: #362E26;            /* rich espresso / almost black text */
      --ink-deep: #221B15;       /* deepest charcoal-espresso for display type */
      --ink-muted: #5C5044;      /* warm secondary body copy */
      --terracotta: #A45337;     /* principal accent and CTAs */
      --terracotta-deep: #82422D;
      --peach: #F9DEC7;          /* large organic backdrop shapes */
      --peach-dark: #F6D3B4;
      --clay: #CE916E;           /* sculpture earth tone */
      --olive: #777B45;          /* wordmark / secondary botanical detail */
      --sage: #4C7262;           /* plant leaves / character clothing */
      --sage-tint: #C8D3B8;      /* soft botanical seal fill */
      --mustard: #EFB15C;        /* tiny badge or flower accent */
      --stroke: #DCCEBB;         /* delicate outlines and dividers */
      --serif: var(--font-nexus-serif), "Iowan Old Style", "Baskerville", "Palatino Linotype", "Book Antiqua", Georgia, "Times New Roman", serif;
      --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
      --ease-spring: cubic-bezier(0.34, 1.45, 0.64, 1);
    }

    *, *::before, *::after {
      box-sizing: border-box;
      font-family: var(--serif) !important;
    }

    html {
      background-color: var(--paper);
      color: var(--ink);
      font-family: var(--serif);
      font-size: 16px;
      line-height: 1.6;
      scroll-behavior: smooth;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    body, .nx-body {
      margin: 0;
      padding: 0;
      background-color: var(--paper);
      color: var(--ink);
      font-family: var(--serif);
      overflow-x: hidden;
      position: relative;
      /* Subtle tactile paper weave using pure CSS gradients */
      background-image:
        radial-gradient(rgba(164, 83, 55, 0.03) 1px, transparent 0),
        radial-gradient(rgba(54, 46, 38, 0.025) 1px, transparent 0);
      background-size: 28px 28px;
      background-position: 0 0, 14px 14px;
    }

    img, svg {
      max-width: 100%;
      display: block;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button, input, textarea, select {
      font: inherit;
      color: inherit;
      background: none;
      border: none;
    }

    button {
      cursor: pointer;
    }

    :focus-visible {
      outline: 2px solid var(--terracotta);
      outline-offset: 4px;
      border-radius: 4px;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    /* ==========================================================================
       02. LAYOUT CONTAINERS & REUSABLE EDITORIAL COMPONENTS
       ========================================================================== */
    .nx-container {
      width: 100%;
      max-width: 1360px;
      margin: 0 auto;
      padding: 0 clamp(1.25rem, 4vw, 3.5rem);
      position: relative;
      z-index: 2;
    }

    /* Tactile Primary Button */
    .nx-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.65rem;
      background-color: var(--terracotta);
      color: var(--paper-light);
      font-size: 0.95rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      padding: 0.95rem 2.1rem;
      border-radius: 999px;
      position: relative;
      overflow: hidden;
      box-shadow: 0 6px 18px -4px rgba(130, 66, 45, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.18);
      transition: transform 0.25s var(--ease-out-expo), background-color 0.25s ease, box-shadow 0.25s ease;
      white-space: nowrap;
      user-select: none;
    }

    .nx-btn::before {
      content: "";
      position: absolute;
      inset: 0;
      background-color: var(--terracotta-deep);
      transform: scaleX(0);
      transform-origin: left center;
      transition: transform 0.35s var(--ease-out-expo);
      z-index: 0;
      border-radius: inherit;
    }

    .nx-btn:hover::before,
    .nx-btn:focus-visible::before {
      transform: scaleX(1);
    }

    .nx-btn > * {
      position: relative;
      z-index: 1;
    }

    .nx-btn:hover {
      box-shadow: 0 10px 24px -4px rgba(130, 66, 45, 0.42);
    }

    .nx-btn:active,
    .nx-btn.is-pressed {
      transform: scale(0.96) translateY(2px) !important;
      box-shadow: 0 3px 10px -2px rgba(130, 66, 45, 0.3);
    }

    .nx-btn-arrow {
      width: 18px;
      height: 14px;
      transition: transform 0.3s var(--ease-spring);
      flex-shrink: 0;
    }

    .nx-btn:hover .nx-btn-arrow {
      transform: translateX(6px);
    }

    /* Drawn Editorial Link */
    .nx-drawn-link {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      font-size: 1.05rem;
      font-style: italic;
      color: var(--ink);
      position: relative;
      padding-bottom: 4px;
      white-space: nowrap;
    }

    .nx-drawn-link::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: 0;
      width: 100%;
      height: 2px;
      background-color: var(--terracotta);
      border-radius: 2px;
      transform: scaleX(0.28);
      transform-origin: left center;
      transition: transform 0.32s var(--ease-out-expo);
    }

    .nx-drawn-link:hover::after,
    .nx-drawn-link:focus-visible::after {
      transform: scaleX(1);
    }

    /* Section Header Pattern */
    .nx-kicker {
      display: inline-block;
      font-size: 0.85rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--terracotta);
      font-weight: 700;
      margin-bottom: 0.75rem;
    }

    .nx-section-title {
      font-size: clamp(2.4rem, 4.8vw, 4.4rem);
      line-height: 1.06;
      letter-spacing: -0.025em;
      color: var(--ink-deep);
      margin: 0 0 1.25rem 0;
      font-weight: 700;
      text-wrap: balance;
    }

    /* ==========================================================================
       03. TOP NAVIGATION BAR (3-Zone Contract + Bespoke Paper Mobile Menu)
       ========================================================================== */
    .nx-header {
      position: relative;
      z-index: 40;
      padding: 1.65rem 0 0.75rem;
    }

    .nx-nav-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }

    .nx-wordmark {
      font-size: clamp(2.1rem, 3vw, 2.65rem);
      font-weight: 700;
      color: var(--olive);
      letter-spacing: -0.03em;
      line-height: 1;
      display: inline-block;
      transform-origin: left center;
      transition: transform 0.3s var(--ease-spring), color 0.25s ease;
      white-space: nowrap;
      flex-shrink: 0;
    }

    .nx-wordmark:hover {
      transform: rotate(-2deg) translateY(-1px);
      color: var(--terracotta);
    }

    .nx-nav-links {
      display: flex;
      align-items: center;
      gap: clamp(1.6rem, 3.2vw, 3.1rem);
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .nx-nav-link {
      font-size: 1.08rem;
      color: var(--ink-deep);
      padding: 0.35rem 0;
      position: relative;
      display: inline-block;
      white-space: nowrap;
      transition: color 0.2s ease, transform 0.2s var(--ease-out-expo);
    }

    .nx-nav-link::after {
      content: "";
      position: absolute;
      left: 0;
      right: 0;
      bottom: -2px;
      height: 2.5px;
      background-color: var(--terracotta);
      border-radius: 2px;
      transform: scaleX(0);
      transform-origin: left center;
      transition: transform 0.28s var(--ease-out-expo);
    }

    .nx-nav-link:hover,
    .nx-nav-link.is-active {
      color: var(--terracotta);
    }

    .nx-nav-link:hover {
      transform: translateY(-1px);
    }

    .nx-nav-link:hover::after,
    .nx-nav-link.is-active::after {
      transform: scaleX(1);
    }

    .nx-nav-actions {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-shrink: 0;
    }

    .nx-nav-cta {
      padding: 0.68rem 1.65rem;
      font-size: 0.98rem;
      letter-spacing: 0.01em;
      background-color: #93452B;
    }

    .nx-mobile-toggle {
      display: none;
      align-items: center;
      justify-content: center;
      gap: 0.45rem;
      min-width: 46px;
      min-height: 46px;
      padding: 0.5rem 0.95rem;
      border-radius: 999px;
      border: 1.5px solid var(--ink);
      background-color: var(--paper-light);
      color: var(--ink-deep);
      font-size: 0.92rem;
      font-weight: 600;
    }

    /* Bespoke Warm Paper Mobile Menu Panel */
    .nx-mobile-panel {
      display: none;
      position: fixed;
      inset: 0;
      z-index: 100;
      background-color: rgba(54, 46, 38, 0.35);
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.32s var(--ease-out-expo);
    }

    .nx-mobile-panel.is-open {
      opacity: 1;
      pointer-events: auto;
    }

    .nx-mobile-sheet {
      position: absolute;
      top: 0.85rem;
      right: 0.85rem;
      left: 0.85rem;
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 28px;
      padding: 1.5rem 1.75rem 2.25rem;
      box-shadow: 0 24px 48px rgba(34, 27, 21, 0.18);
      transform: translateY(-18px) rotate(-1deg) scale(0.97);
      transition: transform 0.38s var(--ease-spring);
      overflow: hidden;
    }

    .nx-mobile-panel.is-open .nx-mobile-sheet {
      transform: translateY(0) rotate(0deg) scale(1);
    }

    .nx-mobile-sheet-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 1.5rem;
      padding-bottom: 1rem;
      border-bottom: 1px solid var(--stroke);
    }

    .nx-mobile-close {
      min-width: 44px;
      min-height: 44px;
      padding: 0.4rem 0.95rem;
      border-radius: 999px;
      border: 1px solid var(--stroke);
      background-color: var(--paper);
      font-size: 0.92rem;
      font-weight: 600;
    }

    .nx-mobile-list {
      list-style: none;
      margin: 0 0 1.75rem 0;
      padding: 0;
      display: flex;
      flex-direction: column;
      gap: 0.65rem;
    }

    .nx-mobile-list a {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      font-size: 1.75rem;
      font-weight: 700;
      color: var(--ink-deep);
      padding: 0.4rem 0;
      border-bottom: 1px dashed var(--stroke);
      transform: translateY(12px);
      opacity: 0;
      transition: transform 0.36s var(--ease-out-expo), opacity 0.36s ease, color 0.2s ease;
    }

    .nx-mobile-panel.is-open .nx-mobile-list li:nth-child(1) a { transition-delay: 0.05s; transform: translateY(0); opacity: 1; }
    .nx-mobile-panel.is-open .nx-mobile-list li:nth-child(2) a { transition-delay: 0.10s; transform: translateY(0); opacity: 1; }
    .nx-mobile-panel.is-open .nx-mobile-list li:nth-child(3) a { transition-delay: 0.15s; transform: translateY(0); opacity: 1; }
    .nx-mobile-panel.is-open .nx-mobile-list li:nth-child(4) a { transition-delay: 0.20s; transform: translateY(0); opacity: 1; }
    .nx-mobile-panel.is-open .nx-mobile-list li:nth-child(5) a { transition-delay: 0.25s; transform: translateY(0); opacity: 1; }

    .nx-mobile-list a span.nx-mobile-idx {
      font-size: 0.9rem;
      font-style: italic;
      color: var(--terracotta);
      font-weight: 400;
    }

    /* ==========================================================================
       04. HERO SECTION — REFERENCE DNA & LAYERED ARTWORK
       ========================================================================== */
    .nx-hero {
      position: relative;
      padding: 0.75rem 0 2.5rem;
      overflow: visible;
    }

    /* Sweeping Organic Peach Backdrop */
    .nx-hero-peach-bg {
      position: absolute;
      top: -115px;
      right: -2%;
      width: 82%;
      height: 840px;
      pointer-events: none;
      z-index: 0;
      transform-origin: 78% 22%;
    }

    .nx-hero-peach-bg svg {
      width: 100%;
      height: 100%;
      overflow: visible;
    }

    /* Corner Olive Botanical Sprigs */
    .nx-corner-sprig {
      position: absolute;
      pointer-events: none;
      z-index: 3;
    }

    .nx-corner-sprig--left {
      bottom: 85px;
      left: -8px;
      width: clamp(68px, 7.5vw, 112px);
      transform-origin: bottom left;
      animation: nxSwayLeft 7s ease-in-out infinite alternate;
    }

    .nx-corner-sprig--right {
      bottom: 135px;
      right: -6px;
      width: clamp(68px, 7.2vw, 106px);
      transform-origin: bottom right;
      animation: nxSwayRight 6.5s ease-in-out infinite alternate;
    }

    @keyframes nxSwayLeft {
      0% { transform: rotate(0deg); }
      100% { transform: rotate(4.5deg); }
    }

    @keyframes nxSwayRight {
      0% { transform: rotate(0deg); }
      100% { transform: rotate(-4.5deg); }
    }

    /* Main Hero Stage Grid */
    .nx-hero-stage {
      position: relative;
      display: grid;
      grid-template-columns: minmax(440px, 620px) 1fr;
      align-items: start;
      min-height: 545px;
      padding-top: 1.15rem;
      z-index: 2;
    }

    .nx-hero-copy {
      position: relative;
      z-index: 5;
      padding-top: 0.75rem;
    }

    .nx-hero-title {
      font-size: clamp(3.25rem, 5.75vw, 5.65rem);
      line-height: 1.01;
      letter-spacing: -0.032em;
      font-weight: 700;
      color: var(--ink-deep);
      margin: 0 0 1.35rem 0;
    }
    .nx-line-inner--1 {
      white-space: nowrap;
    }

    .nx-line-mask {
      display: block;
      overflow: hidden;
      padding-bottom: 0.08em;
      margin-bottom: -0.06em;
    }

    .nx-line-inner {
      display: inline-block;
      transform-origin: left bottom;
      will-change: transform;
    }

    .nx-human-word {
      color: var(--terracotta);
      position: relative;
      display: inline-block;
      padding-right: 0.04em;
    }

    .nx-human-underline {
      position: absolute;
      left: 2%;
      bottom: -0.07em;
      width: 96%;
      height: 0.22em;
      overflow: visible;
      pointer-events: none;
    }

    .nx-human-underline path {
      stroke-dasharray: 320;
      stroke-dashoffset: 0;
      transition: stroke-dashoffset 0.9s var(--ease-out-expo);
    }

    .nx-hero-sub {
      font-size: clamp(1.08rem, 1.45vw, 1.32rem);
      line-height: 1.48;
      color: var(--ink);
      max-width: 390px;
      margin: 0 0 2.15rem 0;
      font-weight: 400;
    }

    .nx-hero-cta-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1.35rem;
    }

    .nx-hero-cta {
      background-color: #9E472A;
      padding: 1.02rem 2.35rem;
      font-size: 0.98rem;
      letter-spacing: 0.045em;
    }

    /* Hero Visual Collage (Clay Cluster + Doodles + Character) */
    .nx-hero-visuals {
      position: relative;
      min-height: 530px;
      width: 100%;
      z-index: 3;
    }

    /* 3D Clay Botanical Cluster */
    .nx-clay-cluster-wrap {
      position: absolute;
      left: -21%;
      bottom: 12px;
      width: clamp(310px, 37vw, 495px);
      z-index: 3;
      pointer-events: none;
      animation: nxFloatClay 6.2s ease-in-out infinite alternate;
    }

    .nx-clay-cluster-img {
      width: 100%;
      height: auto;
      filter: drop-shadow(0 18px 26px rgba(84, 46, 28, 0.12));
    }

    /* Right-side Botanical Fan & Mustard Sun Dot behind Clay Cluster */
    .nx-clay-doodle-right {
      position: absolute;
      right: -7%;
      bottom: 18%;
      width: 22%;
      height: auto;
      z-index: 2;
      overflow: visible;
    }

    @keyframes nxFloatClay {
      0% { transform: translateY(0px) rotate(0deg); }
      100% { transform: translateY(-7px) rotate(0.6deg); }
    }

    /* Illustrated Character Holding Sprout */
    .nx-character-wrap {
      position: absolute;
      right: 2%;
      top: -32px;
      width: clamp(255px, 27.5vw, 382px);
      z-index: 4;
      transform-origin: bottom center;
    }

    .nx-character-img {
      width: 100%;
      height: auto;
      filter: drop-shadow(0 14px 22px rgba(54, 46, 38, 0.09));
    }

    /* Shoulder Motion Lines SVG */
    .nx-shoulder-lines {
      position: absolute;
      top: 10%;
      right: 5%;
      width: 18%;
      height: auto;
      overflow: visible;
      pointer-events: none;
    }

    /* Interactive Sprout Pulse Halo */
    .nx-sprout-spark {
      position: absolute;
      top: 2%;
      left: 6%;
      width: 34%;
      height: 22%;
      pointer-events: none;
      animation: nxSproutNod 4.2s ease-in-out infinite alternate;
      transform-origin: bottom center;
    }

    @keyframes nxSproutNod {
      0% { transform: rotate(-1.5deg) scale(1); }
      100% { transform: rotate(2.5deg) scale(1.03); }
    }

    /* Stroke-draw animation utility for SVG ink doodles */
    .nx-draw-path {
      stroke-dasharray: 600;
      stroke-dashoffset: 0;
    }

    .js-anim-ready .nx-draw-path.is-drawing {
      animation: nxDrawStroke 1.35s var(--ease-out-expo) forwards;
    }

    @keyframes nxDrawStroke {
      from { stroke-dashoffset: 600; }
      to { stroke-dashoffset: 0; }
    }

    /* Lower Hero Edge / Manifesto Teaser Strip (Directly from Reference) */
    .nx-hero-lower {
      position: relative;
      z-index: 5;
      margin-top: 0.5rem;
      padding-top: 1rem;
      display: grid;
      grid-template-columns: minmax(260px, 1.05fr) minmax(240px, 0.95fr) minmax(300px, 1.15fr);
      align-items: center;
      gap: 2rem;
    }

    .nx-lower-headline {
      font-size: clamp(1.85rem, 2.8vw, 2.65rem);
      line-height: 1.08;
      letter-spacing: -0.025em;
      font-weight: 700;
      color: var(--ink-deep);
      margin: 0;
      padding-left: 2.5rem;
    }

    .nx-lower-copy {
      font-size: clamp(0.98rem, 1.12vw, 1.1rem);
      line-height: 1.52;
      color: var(--ink);
      margin: 0;
      padding-left: 1.75rem;
      padding-right: 1.25rem;
      border-left: 2px solid var(--peach-dark);
    }

    .nx-lower-badges-cluster {
      position: relative;
      min-height: 175px;
      display: flex;
      align-items: center;
      justify-content: flex-end;
    }

    /* Peach Mound Behind Clay Flower */
    .nx-flower-mound {
      position: absolute;
      left: -8%;
      bottom: -42px;
      width: 118%;
      height: 195px;
      z-index: 0;
      pointer-events: none;
    }

    /* Terracotta 12-Point Checkmark Starburst */
    .nx-starburst-stamp {
      position: relative;
      z-index: 3;
      width: 68px;
      height: 68px;
      margin-left: 14px;
      margin-right: -6px;
      margin-top: -36px;
      flex-shrink: 0;
      transition: transform 0.35s var(--ease-spring);
      cursor: pointer;
    }

    .nx-starburst-stamp:hover {
      transform: rotate(14deg) scale(1.08);
    }

    /* Clay Flower Stem Cutout */
    .nx-clay-flower-wrap {
      position: relative;
      z-index: 2;
      width: clamp(165px, 17vw, 235px);
      margin-bottom: -28px;
      flex-shrink: 0;
      transform-origin: bottom center;
      animation: nxFlowerSway 5.8s ease-in-out infinite alternate;
    }

    @keyframes nxFlowerSway {
      0% { transform: rotate(-1deg); }
      100% { transform: rotate(1.5deg); }
    }

    /* Circular Botanical Stamps (CASUAL BADGES & CLAY-MADE CULTURE) */
    .nx-seal-pair {
      position: relative;
      z-index: 4;
      display: flex;
      align-items: center;
      margin-left: -18px;
    }

    .nx-seal-badge {
      width: clamp(96px, 9.5vw, 124px);
      height: clamp(96px, 9.5vw, 124px);
      border-radius: 50%;
      padding: 0;
      background: none;
      transition: transform 0.4s var(--ease-spring);
      flex-shrink: 0;
    }

    .nx-seal-badge--sage {
      transform: rotate(-12deg) translateY(-14px);
    }

    .nx-seal-badge--mustard {
      width: clamp(104px, 10.2vw, 134px);
      height: clamp(104px, 10.2vw, 134px);
      margin-left: -14px;
      transform: rotate(11deg) translateY(12px);
    }

    .nx-seal-badge:hover,
    .nx-seal-badge:focus-visible {
      transform: rotate(0deg) scale(1.08);
    }

    /* ==========================================================================
       05. SECTION 02 — MANIFESTO ("Good ideas grow on people.")
       ========================================================================== */
    .nx-manifesto {
      position: relative;
      padding: clamp(5rem, 9vw, 8.5rem) 0 clamp(4.5rem, 8vw, 7.5rem);
      overflow: hidden;
    }

    .nx-manifesto-bg {
      position: absolute;
      inset: 0;
      pointer-events: none;
      z-index: 0;
    }

    .nx-manifesto-grid {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: clamp(2.5rem, 5vw, 5rem);
      align-items: center;
      position: relative;
      z-index: 2;
    }

    .nx-manifesto-statement {
      font-size: clamp(2.75rem, 5.4vw, 5.1rem);
      line-height: 1.04;
      letter-spacing: -0.03em;
      color: var(--ink-deep);
      margin: 0 0 1.75rem 0;
      font-weight: 700;
      text-wrap: balance;
    }

    .nx-manifesto-statement em {
      color: var(--terracotta);
      font-style: italic;
      font-weight: 700;
    }

    .nx-manifesto-lead {
      font-size: clamp(1.15rem, 1.45vw, 1.38rem);
      line-height: 1.62;
      color: var(--ink);
      margin: 0 0 1.5rem 0;
      max-width: 58ch;
    }

    .nx-manifesto-proof {
      margin-top: 2.25rem;
      padding-top: 1.35rem;
      border-top: 1px solid var(--stroke);
      font-size: 0.98rem;
      color: var(--ink-muted);
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.65rem 1rem;
      font-variant-numeric: tabular-nums;
    }

    .nx-manifesto-proof strong {
      color: var(--terracotta-deep);
      font-weight: 700;
    }

    .nx-manifesto-card {
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 32px 18px 36px 22px;
      padding: clamp(2rem, 3.5vw, 3rem);
      position: relative;
      box-shadow: 0 18px 40px -16px rgba(54, 46, 38, 0.1);
    }

    .nx-manifesto-seals {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.5rem;
    }

    .nx-stamp-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.6rem;
      padding: 0.55rem 1rem;
      border-radius: 999px;
      border: 1.5px dashed var(--terracotta);
      background-color: var(--paper);
      color: var(--terracotta-deep);
      font-size: 0.84rem;
      font-weight: 700;
      letter-spacing: 0.09em;
      text-transform: uppercase;
      transition: transform 0.25s var(--ease-spring), background-color 0.2s ease;
    }

    .nx-stamp-btn.is-active,
    .nx-stamp-btn:hover {
      background-color: var(--peach);
      transform: rotate(-2deg) scale(1.03);
    }

    .nx-manifesto-note {
      font-size: 1.12rem;
      line-height: 1.6;
      color: var(--ink);
      font-style: italic;
      margin: 0 0 1.5rem 0;
      min-height: 4.8em;
    }

    .nx-manifesto-art-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px dashed var(--stroke);
    }

    /* ==========================================================================
       06. SECTION 03 — SERVICES ("What we make bloom.")
       ========================================================================== */
    .nx-services {
      position: relative;
      padding: clamp(4.5rem, 8vw, 7.5rem) 0;
    }

    .nx-services-header {
      display: flex;
      flex-wrap: wrap;
      align-items: flex-end;
      justify-content: space-between;
      gap: 2rem;
      margin-bottom: 3.25rem;
    }

    .nx-services-intro {
      max-width: 440px;
      font-size: 1.12rem;
      color: var(--ink-muted);
      margin: 0;
    }

    .nx-services-grid {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 1.75rem;
    }

    .nx-service-card {
      grid-column: span 6;
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      padding: clamp(1.85rem, 3vw, 2.65rem);
      position: relative;
      transition: transform 0.35s var(--ease-out-expo), box-shadow 0.35s var(--ease-out-expo), border-color 0.3s ease;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      overflow: hidden;
    }

    /* Irregular handmade art-paper corner radii */
    .nx-service-card:nth-child(1) { border-radius: 28px 14px 30px 18px; }
    .nx-service-card:nth-child(2) { border-radius: 16px 32px 18px 28px; }
    .nx-service-card:nth-child(3) { border-radius: 30px 18px 14px 32px; }
    .nx-service-card:nth-child(4) { border-radius: 18px 28px 32px 16px; }

    /* Folded paper corner detail */
    .nx-service-card::after {
      content: "";
      position: absolute;
      top: 0;
      right: 0;
      width: 34px;
      height: 34px;
      background: linear-gradient(225deg, var(--paper) 46%, var(--peach-dark) 50%, var(--stroke) 56%);
      border-bottom-left-radius: 10px;
      pointer-events: none;
    }

    .nx-service-card:hover {
      transform: translateY(-5px) rotate(-0.4deg);
      box-shadow: 0 20px 38px -16px rgba(54, 46, 38, 0.14);
      border-color: var(--clay);
    }

    .nx-service-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.25rem;
    }

    .nx-service-num {
      font-size: 1.05rem;
      font-style: italic;
      font-weight: 700;
      color: var(--terracotta);
      font-variant-numeric: tabular-nums;
    }

    .nx-service-motif {
      width: 56px;
      height: 56px;
      flex-shrink: 0;
      transition: transform 0.4s var(--ease-spring);
    }

    .nx-service-card:hover .nx-service-motif {
      transform: scale(1.1) rotate(6deg);
    }

    .nx-service-title {
      font-size: clamp(1.55rem, 2.2vw, 2rem);
      line-height: 1.15;
      color: var(--ink-deep);
      margin: 0 0 0.85rem 0;
      font-weight: 700;
    }

    .nx-service-desc {
      font-size: 1.05rem;
      line-height: 1.58;
      color: var(--ink-muted);
      margin: 0 0 1.5rem 0;
    }

    .nx-service-meta {
      font-size: 0.92rem;
      color: var(--olive);
      font-weight: 600;
      margin-bottom: 1.1rem;
    }

    .nx-service-toggle {
      align-self: flex-start;
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--terracotta);
      padding: 0.4rem 0;
      border-bottom: 1.5px solid var(--terracotta);
    }

    .nx-service-drawer {
      display: none;
      margin-top: 1.1rem;
      padding-top: 1.1rem;
      border-top: 1px dashed var(--stroke);
      font-size: 0.98rem;
      color: var(--ink);
    }

    .nx-service-card.is-expanded .nx-service-drawer {
      display: block;
    }

    /* ==========================================================================
       07. SECTION 04 — PROCESS ("From first seed to full bloom.")
       ========================================================================== */
    .nx-process {
      position: relative;
      padding: clamp(5rem, 9vw, 8rem) 0;
      background: linear-gradient(180deg, var(--paper) 0%, rgba(249, 222, 199, 0.38) 50%, var(--paper) 100%);
    }

    .nx-process-layout {
      display: grid;
      grid-template-columns: minmax(280px, 0.9fr) minmax(320px, 1.3fr);
      gap: clamp(2rem, 5vw, 4.5rem);
      align-items: start;
    }

    .nx-process-sticky {
      position: sticky;
      top: 2.5rem;
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 28px;
      padding: clamp(1.75rem, 3vw, 2.5rem);
      box-shadow: 0 16px 34px -16px rgba(54, 46, 38, 0.09);
    }

    .nx-process-nav {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      margin-top: 1.5rem;
    }

    .nx-process-pill {
      padding: 0.5rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--stroke);
      background-color: var(--paper);
      font-size: 0.92rem;
      font-weight: 600;
      color: var(--ink-muted);
      transition: all 0.25s ease;
      font-variant-numeric: tabular-nums;
    }

    .nx-process-pill.is-active,
    .nx-process-pill:hover {
      background-color: var(--terracotta);
      color: var(--paper-light);
      border-color: var(--terracotta);
    }

    .nx-process-timeline {
      position: relative;
      padding-left: 3.5rem;
    }

    /* Continuous Growing Botanical Vine SVG Spine */
    .nx-vine-spine {
      position: absolute;
      left: 0;
      top: 12px;
      bottom: 12px;
      width: 44px;
      pointer-events: none;
    }

    .nx-vine-spine svg {
      width: 100%;
      height: 100%;
      overflow: visible;
    }

    .nx-chapter-card {
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 24px;
      padding: clamp(1.6rem, 2.6vw, 2.25rem);
      margin-bottom: 2rem;
      position: relative;
      transition: transform 0.35s var(--ease-out-expo), border-color 0.3s ease, box-shadow 0.3s ease;
    }

    .nx-chapter-card:last-child {
      margin-bottom: 0;
    }

    .nx-chapter-card.is-reached {
      border-color: var(--terracotta);
      box-shadow: 0 14px 30px -14px rgba(164, 83, 55, 0.16);
    }

    .nx-chapter-marker {
      position: absolute;
      left: -3.15rem;
      top: 1.85rem;
      width: 28px;
      height: 28px;
      border-radius: 50%;
      background-color: var(--paper);
      border: 2px solid var(--olive);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.78rem;
      font-weight: 700;
      color: var(--olive);
      transition: transform 0.35s var(--ease-spring), background-color 0.3s ease, border-color 0.3s ease;
    }

    .nx-chapter-card.is-reached .nx-chapter-marker {
      background-color: var(--terracotta);
      border-color: var(--terracotta);
      color: var(--paper-light);
      transform: scale(1.18);
    }

    .nx-chapter-step {
      font-size: 0.88rem;
      font-style: italic;
      color: var(--terracotta);
      font-weight: 700;
      margin-bottom: 0.35rem;
      display: block;
    }

    .nx-chapter-title {
      font-size: clamp(1.5rem, 2.2vw, 1.95rem);
      margin: 0 0 0.65rem 0;
      color: var(--ink-deep);
    }

    .nx-chapter-body {
      font-size: 1.05rem;
      color: var(--ink-muted);
      margin: 0 0 1rem 0;
    }

    .nx-chapter-artifact {
      font-size: 0.92rem;
      color: var(--sage);
      font-weight: 600;
    }

    /* ==========================================================================
       08. SECTION 05 — SELECTED WORK (Filterable Editorial Case Studies)
       ========================================================================== */
    .nx-work {
      position: relative;
      padding: clamp(5rem, 9vw, 8rem) 0;
    }

    .nx-work-top {
      display: flex;
      flex-wrap: wrap;
      align-items: flex-end;
      justify-content: space-between;
      gap: 1.5rem;
      margin-bottom: 2.75rem;
    }

    .nx-filter-bar {
      display: inline-flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      background-color: var(--paper-light);
      padding: 0.4rem;
      border-radius: 999px;
      border: 1.5px solid var(--stroke);
    }

    .nx-filter-btn {
      padding: 0.55rem 1.25rem;
      border-radius: 999px;
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--ink-muted);
      transition: background-color 0.25s ease, color 0.25s ease, transform 0.2s ease;
      white-space: nowrap;
    }

    .nx-filter-btn.is-active {
      background-color: var(--ink-deep);
      color: var(--paper-light);
    }

    .nx-work-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
    }

    .nx-work-card {
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 26px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: transform 0.38s var(--ease-out-expo), box-shadow 0.38s var(--ease-out-expo);
    }

    .nx-work-card:hover {
      transform: translateY(-6px) rotate(0.4deg);
      box-shadow: 0 22px 42px -16px rgba(54, 46, 38, 0.15);
    }

    .nx-work-art {
      position: relative;
      height: 250px;
      overflow: hidden;
      padding: 1.5rem;
      display: flex;
      align-items: center;
      justify-content: center;
      border-bottom: 1px solid var(--stroke);
    }

    .nx-work-art--solstice { background-color: var(--peach); }
    .nx-work-art--loom { background-color: #E7E8D5; }
    .nx-work-art--kith { background-color: #F3D5B8; }

    .nx-work-art svg,
    .nx-work-art img {
      transition: transform 0.45s var(--ease-out-expo);
    }

    .nx-work-card:hover .nx-work-art .nx-art-layer-back {
      transform: translateY(-6px) scale(1.04) rotate(-2deg);
    }

    .nx-work-card:hover .nx-work-art .nx-art-layer-front {
      transform: translateY(-10px) scale(1.06) rotate(2deg);
    }

    .nx-work-body {
      padding: 1.75rem;
      display: flex;
      flex-direction: column;
      flex: 1;
    }

    .nx-work-meta {
      font-size: 0.88rem;
      color: var(--ink-muted);
      margin-bottom: 0.55rem;
      font-variant-numeric: tabular-nums;
    }

    .nx-work-title {
      font-size: 1.55rem;
      line-height: 1.18;
      color: var(--ink-deep);
      margin: 0 0 0.65rem 0;
      font-weight: 700;
    }

    .nx-work-summary {
      font-size: 1rem;
      color: var(--ink-muted);
      margin: 0 0 1.25rem 0;
      flex: 1;
    }

    .nx-work-metric {
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--terracotta-deep);
      padding: 0.75rem 0;
      border-top: 1px dashed var(--stroke);
      border-bottom: 1px dashed var(--stroke);
      margin-bottom: 1.25rem;
      font-variant-numeric: tabular-nums;
    }

    .nx-work-open-btn {
      align-self: flex-start;
      font-size: 0.98rem;
      font-weight: 700;
      color: var(--ink-deep);
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      padding: 0.35rem 0;
      border-bottom: 1.5px solid var(--terracotta);
    }

    /* Case Study Modal Dialog */
    .nx-modal-backdrop {
      position: fixed;
      inset: 0;
      z-index: 120;
      background-color: rgba(34, 27, 21, 0.48);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 1.25rem;
    }

    .nx-modal-backdrop.is-open {
      display: flex;
    }

    .nx-modal-card {
      background-color: var(--paper-light);
      border: 2px solid var(--stroke);
      border-radius: 28px;
      max-width: 680px;
      width: 100%;
      padding: clamp(1.75rem, 3.5vw, 2.75rem);
      box-shadow: 0 28px 60px rgba(34, 27, 21, 0.25);
      position: relative;
      max-height: 90vh;
      overflow-y: auto;
    }

    .nx-modal-close {
      position: absolute;
      top: 1.25rem;
      right: 1.25rem;
      min-width: 44px;
      min-height: 44px;
      padding: 0.4rem 0.95rem;
      border-radius: 999px;
      border: 1.5px solid var(--stroke);
      background-color: var(--paper);
      font-weight: 700;
    }

    /* ==========================================================================
       09. SECTION 06 — CLIENT LOVE / TESTIMONIALS (Tactile Paper Note)
       ========================================================================== */
    .nx-testimonials {
      position: relative;
      padding: clamp(4.5rem, 8vw, 7.5rem) 0;
    }

    .nx-quote-stage {
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 36px 20px 32px 24px;
      padding: clamp(2.25rem, 5vw, 4.25rem);
      position: relative;
      box-shadow: 0 22px 46px -18px rgba(54, 46, 38, 0.12);
      max-width: 1060px;
      margin: 0 auto;
    }

    .nx-quote-text {
      font-size: clamp(1.45rem, 2.5vw, 2.25rem);
      line-height: 1.38;
      color: var(--ink-deep);
      font-style: italic;
      margin: 1rem 0 2rem 0;
      transition: transform 0.35s var(--ease-out-expo), opacity 0.35s ease;
    }

    .nx-quote-footer {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1.5rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--stroke);
    }

    .nx-quote-author strong {
      display: block;
      font-size: 1.2rem;
      color: var(--ink-deep);
    }

    .nx-quote-author span {
      font-size: 0.98rem;
      color: var(--ink-muted);
    }

    .nx-quote-controls {
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }

    .nx-IconBtn {
      min-width: 48px;
      min-height: 48px;
      padding: 0 1.15rem;
      border-radius: 999px;
      border: 1.5px solid var(--ink);
      background-color: var(--paper);
      color: var(--ink-deep);
      font-weight: 700;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.4rem;
      transition: background-color 0.2s ease, color 0.2s ease, transform 0.2s ease;
    }

    .nx-IconBtn:hover {
      background-color: var(--terracotta);
      border-color: var(--terracotta);
      color: var(--paper-light);
      transform: translateY(-2px);
    }

    /* ==========================================================================
       10. SECTION 07 — CLOSING CTA, INTERACTIVE SEED BRIEF & ORGANIC FOOTER
       ========================================================================== */
    .nx-closing {
      position: relative;
      padding: clamp(5rem, 9vw, 8rem) 0 0;
      overflow: hidden;
    }

    .nx-closing-grid {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: clamp(2.5rem, 5vw, 4.5rem);
      align-items: start;
      padding-bottom: clamp(4rem, 7vw, 6.5rem);
    }

    .nx-closing-title {
      font-size: clamp(2.85rem, 5.6vw, 5.25rem);
      line-height: 1.02;
      letter-spacing: -0.03em;
      color: var(--ink-deep);
      margin: 0 0 1.25rem 0;
      font-weight: 700;
      text-wrap: balance;
    }

    .nx-closing-title span {
      color: var(--terracotta);
      font-style: italic;
    }

    .nx-brief-card {
      background-color: var(--paper-light);
      border: 1.5px solid var(--stroke);
      border-radius: 28px;
      padding: clamp(1.75rem, 3.2vw, 2.75rem);
      box-shadow: 0 20px 44px -18px rgba(54, 46, 38, 0.12);
    }

    .nx-scope-chips {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      margin: 0.65rem 0 1.35rem;
    }

    .nx-scope-chip {
      padding: 0.5rem 1rem;
      border-radius: 999px;
      border: 1.5px solid var(--stroke);
      background-color: var(--paper);
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--ink);
      transition: all 0.2s ease;
    }

    .nx-scope-chip[aria-pressed="true"] {
      background-color: var(--sage);
      border-color: var(--sage);
      color: var(--paper-light);
    }

    .nx-field {
      margin-bottom: 1.15rem;
    }

    .nx-field label {
      display: block;
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--ink-deep);
      margin-bottom: 0.35rem;
    }

    .nx-input,
    .nx-textarea {
      width: 100%;
      padding: 0.85rem 1.1rem;
      border-radius: 14px;
      border: 1.5px solid var(--stroke);
      background-color: var(--paper);
      color: var(--ink-deep);
      font-size: 1rem;
      transition: border-color 0.2s ease, background-color 0.2s ease;
    }

    .nx-input:focus,
    .nx-textarea:focus {
      border-color: var(--terracotta);
      background-color: var(--paper-light);
      outline: none;
    }

    .nx-field-error {
      display: none;
      font-size: 0.88rem;
      color: var(--terracotta-deep);
      font-style: italic;
      margin-top: 0.3rem;
    }

    .nx-field-error.is-visible {
      display: block;
    }

    .nx-brief-result {
      display: none;
      margin-top: 1.35rem;
      padding: 1.25rem;
      border-radius: 18px;
      background-color: var(--peach);
      border: 1.5px solid var(--clay);
    }

    .nx-brief-result.is-visible {
      display: block;
    }

    /* Organic Footer */
    .nx-footer {
      position: relative;
      background-color: var(--peach);
      padding: 3.5rem 0 3rem;
      border-top: 1.5px solid var(--peach-dark);
    }

    .nx-footer-grid {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }

    .nx-footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }

    /* ==========================================================================
       11. INTRO & SCROLL REVEAL CHOREOGRAPHY (Tactile Transform + Clip + Spring)
       ========================================================================== */
    .js-anim-ready [data-reveal] {
      opacity: 0;
      transform: translateY(28px) rotate(0.8deg) scale(0.98);
      transition: transform 0.78s var(--ease-out-expo), opacity 0.65s ease;
    }

    .js-anim-ready [data-reveal].is-inview,
    .js-anim-ready [data-reveal][data-inview="true"],
    .js-anim-ready [data-inview="true"] {
      opacity: 1;
      transform: translateY(0) rotate(0deg) scale(1);
    }

    /* Hero Intro Sequence */
    .js-anim-ready .nx-wordmark {
      animation: nxIntroWordmark 0.85s var(--ease-spring) both;
    }

    .js-anim-ready .nx-nav-links li {
      animation: nxIntroNav 0.7s var(--ease-out-expo) both;
    }
    .js-anim-ready .nx-nav-links li:nth-child(1) { animation-delay: 0.08s; }
    .js-anim-ready .nx-nav-links li:nth-child(2) { animation-delay: 0.14s; }
    .js-anim-ready .nx-nav-links li:nth-child(3) { animation-delay: 0.20s; }
    .js-anim-ready .nx-nav-links li:nth-child(4) { animation-delay: 0.26s; }
    .js-anim-ready .nx-nav-links li:nth-child(5) { animation-delay: 0.32s; }

    .js-anim-ready .nx-line-inner--1 {
      animation: nxLineRise 0.85s var(--ease-out-expo) 0.12s both;
    }
    .js-anim-ready .nx-line-inner--2 {
      animation: nxLineRise 0.9s var(--ease-out-expo) 0.26s both;
